code='def suffix_product(k, values):\n    if k < 2:\n        return 1\n    return values[k] * suffix_product(k - 1, values)'
add(14,'b',7,5,'Determine','Determine the value of rec(7,A). Show all your working.',ctx,['B2.4.5'],'B','For values=[8,3,2,5,4], determine suffix_product(4,values). Show the recursive calls and returned values.\n\n'+code,pts((1,'Calls use indices4,3,2,1.'),(1,'Base call at1 returns1.'),(1,'Index2 returns2×1=2.'),(1,'Index3 returns5×2=10.'),(1,'Index4 returns4×10=40.')),assets=[asset(7,'Array and exact source nonbranching recursion')],code=code,tests='assert suffix_product(4,[8,3,2,5,4]) == 40\nassert suffix_product(1,[8,3]) == 1',reason='Preserves nonbranching recursive product trace; replaces pseudocode with executable Python and new data/base boundary.')
ctx='isThere(X,ARR) receives ascending integer array, must use iterative binary search, return true iff present. Example ARR=[0,2,3,4,5,6,7,9]; target7 true,target1 false.'
code='def contains_sorted(target, values):\n    low, high = 0, len(values)-1\n    while low <= high:\n        middle = (low+high)//2\n        if values[middle] == target:\n            return True\n        if values[middle] < target:\n            low = middle+1\n        else:\n            high = middle-1\n    return False'
add(14,'c',7,6,'Construct','Construct an algorithm in pseudocode for the sub-program isThere(X,ARR) as described.',ctx,['B2.4.2'],'B','Construct contains_sorted(target,values) in Python for an ascending list of integers. It must return True exactly when target occurs. Use iterative binary search; do not use in,index,bisect or a linear scan.',pts((1,'Initializes low=0 and high=len(values)-1.'),(1,'Loops while low<=high.'),(1,'Computes middle using integer division.'),(1,'Compares middle item with target and returnsTrue on equality.'),(1,'Moves low to middle+1 or high to middle-1 as appropriate.'),(1,'ReturnsFalse after interval becomes empty.')),solution=code,code=code,tests='for data in [[],[1],[1,3,5],[2,2,2]]:\n    for target in range(-1,8):\n        assert contains_sorted(target,data) == (target in data)',assets=[asset(7,'Sorted example array')],reason='Iterative binary-search construction retained; explicit restrictions assess the search algorithm rather than a library lookup.')
