code='def discounted_in_row(bookings, row):\n    count = 0\n    for kind in bookings[row]:\n        if kind == "D":\n            count += 1\n    return count'
add(15,'b',[8,9],4,'Construct','Construct an algorithm in pseudocode for the sub-program student(CONCERT,ROW) as described.',ctx+' student counts C tickets in specified row; examples row0→3,row1→2.',['B2.2.2','B2.3.3'],'B','Bookings use S for standard,D for discounted and X for unsold. Construct discounted_in_row(bookings,row) in Python to return the number of discounted bookings in the specified row. Assume row is valid.',pts((1,'Initializes a counter to0.'),(1,'Traverses every seat in the selected row.'),(1,'Increments only when the code isD.'),(1,'Returns the completed count after the loop.')),solution=code,code=code,tests='assert discounted_in_row([["D","X","D"],["S","S","X"]],0)==2\nassert discounted_in_row([["D","X","D"],["S","S","X"]],1)==0',assets=[asset(8,'Shared2D grid'),asset(9,'Source subprogram requirements')],reason='Retains row traversal/count reasoning; Python and different coding system make the practice item independently usable.')
code='def total_receipts(bookings):\n    total = 0\n    for row in bookings:\n        for kind in row:\n            if kind == "S":\n                total += 18\n            elif kind == "D":\n                total += 9\n            elif kind == "C":\n                total += 4\n    return total'
